async def notify(self, request: web.Request) -> web.Response:
    """POST /api/notify — send an immediate notification."""
    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    message = data.get("message")
    if not message:
        return web.json_response({"error": "message is required"}, status=400)

    channel_id = data.get("channel_id") or self.default_channel_id
    if not channel_id:
        return web.json_response({"error": "No channel specified"}, status=400)

    raw_channel = self.bot.get_channel(channel_id)
    if not raw_channel:
        try:
            raw_channel = await self.bot.fetch_channel(channel_id)
        except Exception as e:
            return web.json_response({"error": str(e)}, status=500)

    if not hasattr(raw_channel, "send"):
        return web.json_response({"error": "Channel is not messageable"}, status=400)

    # Build poll if specified
    poll_data = data.get("poll")
    poll_obj = None
    if poll_data:
        poll_result = self._build_poll(poll_data)
        if isinstance(poll_result, web.Response):
            return poll_result
        poll_obj = poll_result

    thread_name = data.get("thread_name")
    fmt = data.get("format", "text" if thread_name else "embed")

    # Determine target: create a new thread or send directly to channel
    if thread_name:
        if not hasattr(raw_channel, "create_thread"):
            return web.json_response({"error": "Channel does not support threads"}, status=400)
        thread_result = await raw_channel.create_thread(name=thread_name)  # type: ignore[union-attr]
        # create_thread may return Thread or ThreadWithMessage depending on discord.py version
        thread = thread_result.thread if hasattr(thread_result, "thread") else thread_result  # type: ignore[union-attr]
        target = thread
    else:
        target = raw_channel
        thread = None

    if poll_obj:
        await target.send(content=message, poll=poll_obj)  # type: ignore[union-attr]
    elif fmt == "text":
        await target.send(message)  # type: ignore[union-attr]
    else:
        title = data.get("title")
        embed = self._build_embed(message=message, title=title, color=data.get("color"))
        await target.send(embed=embed)  # type: ignore[union-attr]

    result: dict[str, str] = {"status": "sent"}
    if thread is not None:
        result["thread_id"] = str(thread.id)  # type: ignore[union-attr]
        result["thread_name"] = thread.name  # type: ignore[union-attr]
    return web.json_response(result)

async def schedule(self, request: web.Request) -> web.Response:
    """POST /api/schedule — schedule a notification for later."""
    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    message = data.get("message")
    scheduled_at = data.get("scheduled_at")

    if not message:
        return web.json_response({"error": "message is required"}, status=400)
    if not scheduled_at:
        return web.json_response({"error": "scheduled_at is required"}, status=400)

def bq(sql: str) -> pd.DataFrame:
    # ── LOCAL SNAPSHOT INTERCEPT ──────────────────────────────────────────────
    if _LOCAL_SNAPSHOT_DIR:
        # Route by SQL content to determine which snapshot to load
        _sql_upper = sql.upper()
        if "PLAY_TYPE" in _sql_upper or "FA_RATINGS" in _sql_upper or "FA_TIER" in _sql_upper:
            name = "signal"
        elif "VNINDEX" in _sql_upper and "CLOSE" in _sql_upper:
            name = "vni"
        else:
            name = None  # unknown query type — fall through to real BQ with a warning

        if name is not None:
            if name not in _SNAPSHOT_CACHE:
                _SNAPSHOT_CACHE[name] = _load_local_snapshot(name)
            df = _SNAPSHOT_CACHE[name].copy()

            # Parse date range from the SQL to filter the snapshot
            start_str = _extract_date(sql, "start")
            if df.empty:
                return df

            # Normalize time column to date objects for comparison
            time_col = "time" if "time" in df.columns else df.columns[0]
            df[time_col] = pd.to_datetime(df[time_col]).dt.date

            if start_str:
                start_d = pd.to_datetime(start_str).date()
                df = df[df[time_col] >= start_d]
            end_str = _extract_date(sql, "end")
            if end_str:
                end_d = pd.to_datetime(end_str).date()
                df = df[df[time_col] <= end_d]

            # Restore datetime dtype (callers expect pd.Timestamp)
            df[time_col] = pd.to_datetime(df[time_col])
            return df.reset_index(drop=True)
        else:
            print(
                f"[LOCAL_SNAPSHOT] WARNING: cannot route SQL to a local snapshot "
                f"(no 'play_type'/'fa_ratings'/'VNINDEX' keyword found). "
                f"Falling through to real BigQuery. SQL preview: {sql[:120]!r}",
                flush=True,
            )
    # ── ORIGINAL BIGQUERY PATH ────────────────────────────────────────────────
    import tempfile
    with tempfile.NamedTemporaryFile("w", suffix=".sql", delete=False, encoding="utf-8") as f:
        f.write(sql)
        sql_path = f.name
    try:
        cmd = (f'"{BQ_BIN}" query --use_legacy_sql=false --project_id={PROJECT} '
               f'--format=csv --max_rows=2000000 < "{sql_path}"')
        out = subprocess.run(cmd, capture_output=True, text=True, check=True, shell=True)
    finally:
        os.unlink(sql_path)
    if not out.stdout or not out.stdout.strip():
        return pd.DataFrame()   # zero-row result: bq --format=csv emits nothing, not even a header
    return pd.read_csv(StringIO(out.stdout))

